// The only place that includes <WebView2.h>. Always include THIS header (or com_support.h), never
// WebView2.h directly.
//
// MSVC: works as is.
// MinGW / llvm-mingw: __uuidof() is a template emulation that needs one __CRT_UUID_DECL per interface, so
// webview2_mingw_uuids.h (generated by tools/gen_webview2_uuids.py) supplies them.
// Do NOT include WebView2EnvironmentOptions.h (it needs WRL). Pass nullptr as the environment options.
#pragma once

#include "common.h"

#include <unknwn.h>

#if defined(__clang__)
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wunknown-pragmas"
#endif
#include <WebView2.h>
#if defined(__clang__)
#pragma clang diagnostic pop
#endif

#if defined(__MINGW32__)
#include "webview2_mingw_uuids.h"
#endif
